"""Static workbench UI: same-origin reads only, untrusted data uses textContent."""

WORKBENCH_HTML = r"""<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Authorization workbench</title>
<style>body{font:16px system-ui;margin:2rem;background:#101925;color:#e7eef7}a{color:#86ccff}select,button{font:inherit;padding:.6rem;margin:.4rem;max-width:95%}table{border-collapse:collapse;width:100%;table-layout:fixed}td,th{border:1px solid #526171;padding:.7rem;overflow-wrap:anywhere;vertical-align:top}.difference{background:#473b20}pre{white-space:pre-wrap;overflow-wrap:anywhere}article{min-width:0;overflow-wrap:anywhere}dt{font-weight:600;color:#9fb7d1;margin-top:.7rem}dd{margin:.2rem 0}#columns{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem}article{border:1px solid #526171;padding:1rem} @media(max-width:700px){#columns{grid-template-columns:1fr}}</style>
<a href="/">Dashboard</a><h1>Comparación de autorización offline</h1><p>Solo lectura. Seleccione capturas existentes para A (propietario), B (segunda cuenta) y C (anónimo, opcional). La selección no acredita la identidad ni el permiso.</p>
<form id="choose"><label>A <select id="a"><option value="">Sin captura</option></select></label><label>B <select id="b"><option value="">Sin captura</option></select></label><label>C <select id="c"><option value="">Sin captura</option></select></label><button>Comparar capturas</button></form>
<p id="notice"></p><p id="pending"></p><p id="issues"></p><pre id="assessments"></pre><label><input type="checkbox" id="highlight" checked> Resaltar diferencias observadas</label><p>Valores ocultos por privacidad. absent = campo inexistente; null y empty_* son estados distintos; unavailable = sin cuerpo comparable. Arrays alineados por índice.</p><div id="columns"></div><div style="overflow:auto"><table><caption>Campos JSON, sin conclusiones automáticas</caption><thead id="head"></thead><tbody id="fields"></tbody></table></div><p id="error" role="alert"></p>
<script>
const $=id=>document.getElementById(id);function el(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}let last;
async function get(query=''){const r=await fetch('/api/authorization-workbench'+query);if(!r.ok)throw Error('Selección o referencia no válida');return r.json();}
function draw(d){last=d;$('assessments').textContent=d.saved_assessments.length?JSON.stringify(d.saved_assessments,null,2):'';$('notice').textContent=d.notice;$('pending').textContent='Pendiente: '+d.pending_controls.join(' ');$('issues').textContent='Referencias inutilizables: '+d.reference_issues.length;$('columns').replaceChildren();d.columns.forEach((c,i)=>{const n=el('article','');n.append(el('h2',['A · Propietario','B · Segunda cuenta','C · Anónimo'][i]));const dl=el('dl','');for(const [key,label] of [['evidence_id','Evidence Ledger ID'],['capture_index','Captura'],['source_format','Procedencia'],['method','Método'],['status_code','Estado HTTP'],['response_state','Respuesta'],['response_type','Tipo'],['body_state','Cuerpo'],['saved_classification','Evaluación guardada'],['saved_reason','Razonamiento guardado'],['sha256','SHA-256']]){dl.append(el('dt',label),el('dd',c[key]??'Sin dato guardado'));}for(const [key,value] of Object.entries(c.saved_predicates))dl.append(el('dt',key),el('dd',String(value)));n.append(dl);$('columns').append(n);});$('head').replaceChildren();const h=el('tr','');h.append(el('th','Ruta de propiedad'));d.columns.forEach((_,i)=>h.append(el('th',['A','B','C'][i])));$('head').append(h);$('fields').replaceChildren();d.fields.forEach(f=>{const r=el('tr','');if(f.observed_difference&&$('highlight').checked)r.className='difference';r.append(el('th',f.pointer));f.cells.forEach(c=>r.append(el('td',c.state)));$('fields').append(r);});}
get().then(d=>{for(const id of ['a','b','c'])d.catalog.forEach(c=>{const o=el('option',c.selection+' · '+(c.status_code??'sin respuesta'));o.value=c.selection;$(id).append(o);});draw(d);}).catch(e=>$('error').textContent=e.message);
$('choose').addEventListener('submit',async e=>{e.preventDefault();$('error').textContent='';if(!$('a').value||!$('b').value){$('error').textContent='Seleccione A y B; C es opcional.';return;}const q=new URLSearchParams();for(const id of ['a','b','c'])if($(id).value)q.set(id,$(id).value);try{draw(await get('?'+q));}catch(e){$('error').textContent=e.message;}});$('highlight').addEventListener('change',()=>draw(last));
</script></html>"""
